// ─── Google Maps Fleet Map ─────────────────────────────────────
let _mapsKeyCache = null;
async function getMapsApiKey() {
  if (_mapsKeyCache !== null) return _mapsKeyCache;
  try {
    const r = await api.get('/company/maps-key');
    _mapsKeyCache = r.data?.key || '';
  } catch { _mapsKeyCache = ''; }
  return _mapsKeyCache;
}

function loadGoogleMapsScript(apiKey) {
  return new Promise((resolve, reject) => {
    if (window.google?.maps) { resolve(); return; }
    const existing = document.getElementById('gmap-script');
    if (existing) { existing.addEventListener('load', resolve); return; }
    const script = document.createElement('script');
    script.id = 'gmap-script';
    script.src = `https://maps.googleapis.com/maps/api/js?key=${apiKey}`;
    script.async = true;
    script.onload = resolve;
    script.onerror = reject;
    document.head.appendChild(script);
  });
}

function GoogleFleetMap({ positions }) {
  const mapRef = useRef(null);
  const mapObj = useRef(null);
  const markers = useRef({});
  const [ready, setReady] = useState(false);
  const [noKey, setNoKey] = useState(false);

  // Initialize map once
  useEffect(() => {
    let alive = true;
    getMapsApiKey().then(key => {
      if (!alive) return;
      if (!key) { setNoKey(true); return; }
      loadGoogleMapsScript(key).then(() => {
        if (!alive || !mapRef.current) return;
        // Center on Texas by default; will pan to tech positions once available
        mapObj.current = new window.google.maps.Map(mapRef.current, {
          zoom: 11,
          center: { lat: 29.7604, lng: -95.3698 }, // Houston default
          mapTypeId: 'roadmap',
          styles: [
            { elementType:'geometry', stylers:[{color:'#1d2c3b'}] },
            { featureType:'road', elementType:'geometry', stylers:[{color:'#283f52'}] },
            { featureType:'road', elementType:'labels.text.fill', stylers:[{color:'#8a9aaa'}] },
            { featureType:'water', elementType:'geometry', stylers:[{color:'#0c1921'}] },
            { featureType:'poi', stylers:[{visibility:'off'}] },
            { featureType:'transit', stylers:[{visibility:'off'}] },
            { elementType:'labels.text.fill', stylers:[{color:'#8a9aaa'}] },
          ],
        });
        setReady(true);
      }).catch(() => setNoKey(true));
    });
    return () => { alive = false; };
  }, []);

  // Update markers whenever positions change
  useEffect(() => {
    if (!ready || !mapObj.current || !window.google) return;
    const seen = new Set();

    positions.forEach(p => {
      if (!p.lat || !p.lng) return;
      const key = p.technician_id;
      seen.add(key);
      const pos = { lat: parseFloat(p.lat), lng: parseFloat(p.lng) };
      const color = (p.color || '#5daf7c').replace('#','');

      if (markers.current[key]) {
        markers.current[key].setPosition(pos);
      } else {
        const svgIcon = `<svg xmlns="http://www.w3.org/2000/svg" width="40" height="48" viewBox="0 0 40 48">
          <circle cx="20" cy="20" r="16" fill="#${color}" fill-opacity="0.9" stroke="#fff" stroke-width="2.5"/>
          <text x="20" y="25" text-anchor="middle" font-size="11" font-weight="700" font-family="monospace" fill="#fff">${(p.initials||p.name?.slice(0,2)||'?')}</text>
          <polygon points="14,33 26,33 20,46" fill="#${color}"/>
        </svg>`;
        const icon = { url: 'data:image/svg+xml,' + encodeURIComponent(svgIcon), anchor: new window.google.maps.Point(20,46) };
        const marker = new window.google.maps.Marker({ position: pos, map: mapObj.current, icon, title: p.name || 'Tech' });
        markers.current[key] = marker;
      }
    });

    // Remove markers for techs no longer reporting
    Object.keys(markers.current).forEach(k => {
      if (!seen.has(k)) { markers.current[k].setMap(null); delete markers.current[k]; }
    });

    // Auto-fit bounds if we have multiple positions
    if (positions.length > 0) {
      const bounds = new window.google.maps.LatLngBounds();
      positions.forEach(p => { if(p.lat && p.lng) bounds.extend({ lat: parseFloat(p.lat), lng: parseFloat(p.lng) }); });
      if (positions.length === 1) {
        mapObj.current.setCenter({ lat: parseFloat(positions[0].lat), lng: parseFloat(positions[0].lng) });
        mapObj.current.setZoom(13);
      } else {
        mapObj.current.fitBounds(bounds, 40);
      }
    }
  }, [positions, ready]);

  if (noKey) {
    return (
      <div style={{height:'100%', display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', gap:8, background:'#0d1a20', borderRadius:8}}>
        <div style={{fontSize:24}}>🗺️</div>
        <div style={{fontSize:11, color:'var(--muted)', fontFamily:'var(--font-mono)', textAlign:'center'}}>
          Google Maps API key not configured.<br/>
          <span style={{color:'var(--amber)'}}>Settings → Integrations → Google Maps</span>
        </div>
      </div>
    );
  }

  return (
    <div style={{position:'relative', height:'100%', borderRadius:8, overflow:'hidden'}}>
      <div ref={mapRef} style={{width:'100%', height:'100%'}}/>
      {!ready && (
        <div style={{position:'absolute',inset:0,display:'flex',alignItems:'center',justifyContent:'center',background:'#0d1a20'}}>
          <div style={{fontSize:11,color:'var(--muted)',fontFamily:'var(--font-mono)'}}>Loading map…</div>
        </div>
      )}
      {positions.length === 0 && ready && (
        <div style={{position:'absolute',inset:0,display:'flex',alignItems:'center',justifyContent:'center',pointerEvents:'none'}}>
          <div style={{background:'rgba(8,11,16,.8)',border:'1px solid var(--border)',borderRadius:8,padding:'8px 16px',fontSize:11,color:'var(--muted)',fontFamily:'var(--font-mono)'}}>
            No technicians currently on duty
          </div>
        </div>
      )}
    </div>
  );
}

// ─── Live GPS Canvas Map ──────────────────────────────────────
function GPSCanvas({positions, compact=false}) {
  const ref = useRef(null);
  useEffect(() => {
    const canvas = ref.current; if(!canvas) return;
    const ctx = canvas.getContext("2d");
    const W = canvas.width, H = canvas.height;
    if(!positions?.length) {
      ctx.clearRect(0,0,W,H);
      ctx.fillStyle="#0d1a12"; ctx.fillRect(0,0,W,H);
      ctx.fillStyle="#607b6e"; ctx.font="12px monospace"; ctx.textAlign="center";
      ctx.fillText("No technicians on duty", W/2, H/2);
      return;
    }
    const lats=positions.map(p=>parseFloat(p.lat)), lngs=positions.map(p=>parseFloat(p.lng));
    const minLat=Math.min(...lats)-.004, maxLat=Math.max(...lats)+.004;
    const minLng=Math.min(...lngs)-.006, maxLng=Math.max(...lngs)+.006;
    const toX=lng=>((lng-minLng)/(maxLng-minLng))*W;
    const toY=lat=>H-((lat-minLat)/(maxLat-minLat))*H;

    ctx.clearRect(0,0,W,H);
    ctx.fillStyle="#0d1a12"; ctx.fillRect(0,0,W,H);
    ctx.strokeStyle="#1f3227"; ctx.lineWidth=.5;
    for(let i=0;i<8;i++){
      ctx.beginPath();ctx.moveTo(W*i/7,0);ctx.lineTo(W*i/7,H);ctx.stroke();
      ctx.beginPath();ctx.moveTo(0,H*i/7);ctx.lineTo(W,H*i/7);ctx.stroke();
    }
    positions.forEach(t=>{
      const x=toX(parseFloat(t.lng)),y=toY(parseFloat(t.lat));
      const c=t.color||"#5daf7c";
      ctx.beginPath();ctx.arc(x,y,compact?14:20,0,Math.PI*2);
      ctx.fillStyle=c+"18";ctx.fill();
      ctx.beginPath();ctx.arc(x,y,compact?5:7,0,Math.PI*2);
      ctx.fillStyle=c;ctx.fill();
      ctx.strokeStyle="#0b0e13";ctx.lineWidth=2;ctx.stroke();
      if(!compact){
        ctx.fillStyle=c;ctx.font="bold 9px 'DM Mono'";ctx.textAlign="left";
        ctx.fillText(t.initials||t.name?.slice(0,2)||"?",x+10,y-8);
      }
    });
  },[positions,compact]);

  return <canvas ref={ref} width={compact?280:520} height={compact?160:280} style={{width:"100%",height:"100%",display:"block"}}/>;
}

// ─── Dashboard Stats Card ─────────────────────────────────────
function StatCard({label,value,sub,subUp,loading,accent="var(--blue)"}) {
  return (
    <div style={{background:"var(--surface)",border:"1px solid var(--border)",borderRadius:12,padding:"16px 20px",position:"relative",overflow:"hidden",transition:"transform .15s,box-shadow .15s",cursor:"default"}}
      onMouseEnter={e=>{e.currentTarget.style.transform="translateY(-2px)";e.currentTarget.style.boxShadow="0 8px 24px #00000044";}}
      onMouseLeave={e=>{e.currentTarget.style.transform="";e.currentTarget.style.boxShadow="";}}>
      <div style={{position:"absolute",left:0,top:0,bottom:0,width:3,background:accent,borderRadius:"12px 0 0 12px"}}/>
      <div style={{fontSize:10,fontFamily:"var(--font-mono)",color:"var(--muted)",letterSpacing:".08em",marginBottom:8}}>{label}</div>
      {loading ? (
        <>
          <div className="skel" style={{height:28,width:"60%",marginBottom:6}}/>
          <div className="skel" style={{height:8,width:"40%"}}/>
        </>
      ) : (
        <>
          <div style={{fontFamily:"var(--font-head)",fontSize:32,fontWeight:800,color:accent}}>{value}</div>
          {sub && <div style={{fontSize:11,color:subUp===true?"var(--green2)":subUp===false?"var(--red)":"var(--muted)",marginTop:4,fontFamily:"var(--font-mono)"}}>{sub}</div>}
        </>
      )}
    </div>
  );
}

// ─── Enabled Services Hook ────────────────────────────────────
// Module-level cache + subscriber list so every mounted useCompanyServices()
// hook re-renders when the enabled-services list changes (e.g. after a toggle).
let _servicesCache = null;
let _servicesPromise = null;
const _serviceSubs = new Set();
function _publishServices(next) {
  _servicesCache = next;
  _serviceSubs.forEach(fn => { try { fn(next); } catch {} });
}
async function refreshCompanyServices() {
  try {
    const d = await api.getEnabledServices();
    _publishServices(Array.isArray(d) ? d : ['plumbing']);
  } catch { _publishServices(['plumbing']); }
}
// Optimistic local toggle — updates the cache immediately, then reconciles
// with the server response. Every subscribed hook re-renders both times.
async function toggleCompanyService(service, enabled) {
  const prior = _servicesCache || [];
  const next = enabled ? [...new Set([...prior, service])] : prior.filter(s => s !== service);
  _publishServices(next);
  try {
    const r = await api.toggleService(service, enabled);
    // Always resync from server to stay honest
    await refreshCompanyServices();
    return r;
  } catch (err) {
    _publishServices(prior); // rollback on failure
    throw err;
  }
}

const SERVICE_LABELS = {plumbing:'Plumbing',hvac:'HVAC',electrical:'Electrical',restoration:'Restoration',renovations:'Renovations',pest_control:'Pest Control',pools:'Pools'};
const SERVICE_ICONS  = {plumbing:'🔧',hvac:'❄️',electrical:'⚡',restoration:'🏗️',renovations:'🔨',pest_control:'🪳',pools:'🏊'};
function useCompanyServices() {
  const [services, setServices] = useState(_servicesCache || []);
  useEffect(() => {
    _serviceSubs.add(setServices);
    if (_servicesCache) { setServices(_servicesCache); }
    else if (!_servicesPromise) {
      _servicesPromise = api.getEnabledServices()
        .then(d => { _publishServices(Array.isArray(d) ? d : ['plumbing']); return _servicesCache; })
        .catch(() => { _publishServices(['plumbing']); return _servicesCache; });
    } else {
      _servicesPromise.then(d => setServices(d));
    }
    return () => { _serviceSubs.delete(setServices); };
  }, []);
  return services; // array of lowercase strings e.g. ['plumbing','hvac']
}

// ─── Dashboard ───────────────────────────────────────────────
// Home tab: Housecall Pro-style "what needs me today" (greeting, quick actions,
// today's schedule, needs-attention queue) on top of ServiceTitan-style
// performance (period KPIs with deltas, sales vs collected trend, tech scorecard).
const DASH_PERIODS = [
  {id:'today', label:'Today',      vs:'vs. yesterday'},
  {id:'week',  label:'This Week',  vs:'vs. same point last week'},
  {id:'month', label:'This Month', vs:'vs. same point last month'},
  {id:'year',  label:'This Year',  vs:'vs. same point last year'},
];

// Local-time bounds for a period, plus the same elapsed window one period back
function dashRange(period, now = new Date()) {
  const start = new Date(now); start.setHours(0,0,0,0);
  if (period === 'week')  start.setDate(start.getDate() - start.getDay());
  if (period === 'month') start.setDate(1);
  if (period === 'year')  start.setMonth(0, 1);
  const end = new Date(start);
  const prevStart = new Date(start);
  if (period === 'today') { end.setDate(end.getDate()+1);         prevStart.setDate(prevStart.getDate()-1); }
  if (period === 'week')  { end.setDate(end.getDate()+7);         prevStart.setDate(prevStart.getDate()-7); }
  if (period === 'month') { end.setMonth(end.getMonth()+1);       prevStart.setMonth(prevStart.getMonth()-1); }
  if (period === 'year')  { end.setFullYear(end.getFullYear()+1); prevStart.setFullYear(prevStart.getFullYear()-1); }
  const prevTo = new Date(prevStart.getTime() + (now - start));
  // The "today" chart shows the last 7 days so there's a trend to read
  const trendFrom = new Date(start); if (period === 'today') trendFrom.setDate(trendFrom.getDate()-6);
  return {
    from:start.toISOString(), to:end.toISOString(),
    prev_from:prevStart.toISOString(), prev_to:prevTo.toISOString(),
    trend_from:trendFrom.toISOString(),
    bucket: period === 'year' ? 'month' : 'day',
    tz: Intl.DateTimeFormat().resolvedOptions().timeZone,
  };
}

function DashboardPage({ onNavigate = () => {} }) {
  const { user } = useAuth();
  const [period, setPeriod] = useState(() => { try { return localStorage.getItem('dps_dashPeriod') || 'month'; } catch { return 'month'; } });
  const [now, setNow] = useState(new Date());
  const range = useMemo(() => dashRange(period), [period]);
  const {data:ov, loading, reload} = useApi(() => api.dashboardOverview(range), [range.from, range.to]);
  const {data:jobs, loading:jobsLoading} = useApi(() => api.getJobs({date: new Date().toLocaleDateString('en-CA')}));
  const [liveStatus, setLiveStatus] = useState({});   // job_id → status pushed over WS
  const [hoverBar, setHoverBar] = useState(null);

  const pickPeriod = p => { setPeriod(p); try { localStorage.setItem('dps_dashPeriod', p); } catch {} };

  useEffect(() => { const t = setInterval(() => setNow(new Date()), 60000); return () => clearInterval(t); }, []);
  useEffect(() => {
    const ws = connectGpsWebSocket(msg => {
      if (msg.type === 'job_status') setLiveStatus(prev => ({ ...prev, [msg.job_id]: msg.status }));
    });
    return () => ws?.close();
  }, []);

  const fmt$  = n => `$${Math.round(parseFloat(n||0)).toLocaleString()}`;
  const fmtK$ = n => { const v = parseFloat(n||0); return v >= 10000 ? `$${(v/1000).toFixed(v>=100000?0:1)}k` : fmt$(v); };
  const pct   = n => n == null ? '—' : `${Math.round(n*100)}%`;
  const cur = ov?.current, prev = ov?.previous;
  const vsLabel = DASH_PERIODS.find(p => p.id === period)?.vs;

  const hour = now.getHours();
  const greeting = hour < 12 ? 'Good morning' : hour < 17 ? 'Good afternoon' : 'Good evening';
  const firstName = user?.first_name || user?.name?.split(' ')[0] || '';

  // Today's schedule, with live status overrides
  const todayJobs = (jobs || [])
    .map(j => liveStatus[j.id] ? { ...j, status: liveStatus[j.id] } : j)
    .filter(j => j.status !== 'cancelled')
    .sort((a,b) => new Date(a.scheduled_start||0) - new Date(b.scheduled_start||0));
  const countBy = s => todayJobs.filter(j => j.status === s).length;

  // ── Pieces ───────────────────────────────────────────────────
  const Delta = ({cur, prev, kind='money'}) => {
    if (prev == null || cur == null) return <span style={{fontSize:11,color:'var(--muted)'}}>—</span>;
    let diff, text;
    if (kind === 'rate') { diff = cur - prev; text = `${diff>=0?'+':''}${Math.round(diff*100)} pts`; }
    else {
      if (!prev) return <span style={{fontSize:11,color:'var(--muted)'}}>{cur ? 'new' : '—'}</span>;
      diff = (cur - prev) / prev; text = `${diff>=0?'+':''}${Math.round(diff*100)}%`;
    }
    const up = diff >= 0, flat = Math.abs(diff) < 0.005;
    const color = flat ? 'var(--muted)' : up ? '#2f9e62' : '#e5484d';
    return <span style={{fontSize:11,fontWeight:700,color,background:flat?'transparent':`${up?'#5daf7c':'#f56565'}14`,borderRadius:4,padding:'1px 6px'}}>{flat?'±0%':`${up?'▲':'▼'} ${text.replace(/^[+-]/,'')}`}</span>;
  };

  const Panel = ({title, right, children, style={}, pad=true}) => (
    <section style={{background:'var(--surface)',border:'1px solid var(--border)',borderRadius:14,display:'flex',flexDirection:'column',minWidth:0,...style}}>
      <div style={{display:'flex',alignItems:'center',gap:8,padding:'14px 18px 10px'}}>
        <h3 style={{fontFamily:'var(--font-head)',fontSize:15,fontWeight:700,margin:0,flex:1}}>{title}</h3>
        {right}
      </div>
      <div style={{padding: pad ? '0 18px 16px' : '0 0 8px', flex:1, minHeight:0}}>{children}</div>
    </section>
  );

  const LinkBtn = ({children, onClick}) => (
    <button onClick={onClick} style={{background:'none',border:'none',color:'var(--blue)',fontSize:12,fontWeight:600,cursor:'pointer',padding:0}}>{children}</button>
  );

  const kpis = [
    {label:'Sales',           value:fmtK$(cur?.sales),     delta:<Delta cur={cur?.sales} prev={prev?.sales}/>,                 accent:'#4a9eff', hint:'Invoiced, excluding voids'},
    {label:'Collected',       value:fmtK$(cur?.collected), delta:<Delta cur={cur?.collected} prev={prev?.collected}/>,         accent:'#5daf7c',  hint:'Payments received'},
    {label:'Jobs Completed',  value:cur?.jobs_completed ?? '—', delta:<Delta cur={cur?.jobs_completed} prev={prev?.jobs_completed}/>, accent:'#6366f1', hint:'Marked complete'},
    {label:'Avg Ticket',      value:fmt$(cur?.avg_ticket), delta:<Delta cur={cur?.avg_ticket} prev={prev?.avg_ticket}/>,       accent:'#a78bfa', hint:'Sales ÷ invoices'},
    {label:'Close Rate',      value:pct(cur?.close_rate),  delta:<Delta cur={cur?.close_rate} prev={prev?.close_rate} kind="rate"/>, accent:'#e8a84a', hint:`${cur?.estimates_presented ?? 0} estimates presented`},
    {label:'Open A/R',        value:fmtK$(ov?.ar?.open),   delta:ov?.ar?.overdue_count ? <span style={{fontSize:11,fontWeight:700,color:'var(--red)'}}>{ov.ar.overdue_count} overdue · {fmtK$(ov.ar.overdue_amount)}</span> : <span style={{fontSize:11,color:'var(--muted)'}}>{ov?.ar?.open_count ?? 0} open invoices</span>, accent:ov?.ar?.overdue_count?'#f56565':'var(--muted)', hint:'Unpaid balance, all time'},
  ];

  const att = ov?.attention || {};
  const attention = [
    {key:'unassigned', n:att.unassigned_jobs,   icon:'🧰', label:'Unassigned jobs',          sub:'Need a technician',                         page:'dispatch',   tone:'#f56565'},
    {key:'unsched',    n:att.unscheduled_jobs,  icon:'📅', label:'Jobs to schedule',         sub:'No date set',                               page:'jobs',       tone:'#e8a84a'},
    {key:'overdue',    n:ov?.ar?.overdue_count, icon:'🧾', label:'Overdue invoices',         sub:`${fmt$(ov?.ar?.overdue_amount)} past due`,  page:'accounting', tone:'#f56565'},
    {key:'estimates',  n:att.open_estimates,    icon:'📝', label:'Estimates awaiting approval', sub:`${fmt$(att.open_estimates_amount)} potential`, page:'jobs',   tone:'#4a9eff'},
    {key:'followups',  n:att.followups_due,     icon:'📞', label:'Follow-ups due',           sub:'Customers to call back',                    page:'customers',  tone:'#a78bfa'},
    {key:'counts',     n:att.counts_due,        icon:'📋', label:'Cycle counts due',         sub:'Truck/warehouse counts',                    page:'settings',   tone:'#a78bfa'},
    {key:'stock',      n:att.low_stock,         icon:'📦', label:'Low-stock items',          sub:'At or below minimum',                       page:'settings',   tone:'#e8a84a'},
  ].filter(a => a.n > 0);

  // Trend chart (sales vs collected)
  const trend = ov?.trend || [];
  const trendMax = Math.max(1, ...trend.map(t => Math.max(t.sales, t.collected)));
  const bucketLabel = b => {
    const [y,m,d] = String(b).slice(0,10).split('-').map(Number);
    const dt = new Date(y, m-1, d);
    if (period === 'year') return dt.toLocaleDateString('en-US',{month:'short'});
    if (period === 'month') return String(d);
    return dt.toLocaleDateString('en-US',{weekday:'short'});
  };
  const bucketTitle = b => {
    const [y,m,d] = String(b).slice(0,10).split('-').map(Number);
    return new Date(y, m-1, d).toLocaleDateString('en-US', period==='year' ? {month:'long',year:'numeric'} : {weekday:'short',month:'short',day:'numeric'});
  };
  const trendSales = trend.reduce((s,t) => s + t.sales, 0);
  const trendCollected = trend.reduce((s,t) => s + t.collected, 0);

  const techs = ov?.techs || [];
  const techMax = Math.max(1, ...techs.map(t => t.sales));

  const quickActions = [
    {label:'New Job',   icon:'＋', primary:true, onClick:() => onNavigate('dispatch', {newJob:true})},
    {label:'Dispatch',  icon:'📋', onClick:() => onNavigate('dispatch')},
    {label:'Customers', icon:'👤', onClick:() => onNavigate('customers')},
    {label:'Reports',   icon:'📊', onClick:() => onNavigate('reports')},
  ];

  return (
    <div style={{animation:'fadeUp .35s ease',display:'flex',flexDirection:'column',gap:16,height:'100%',minHeight:0,overflowY:'auto',padding:'0 0 24px'}} className="scrollbar-thin">

      {/* ── Greeting + quick actions (Housecall Pro) ── */}
      <div style={{display:'flex',alignItems:'flex-end',gap:16,flexWrap:'wrap'}}>
        <div style={{flex:'1 1 260px'}}>
          <div style={{fontSize:12,color:'var(--muted)',fontFamily:'var(--font-mono)'}}>{now.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'})}</div>
          <h1 style={{fontFamily:'var(--font-head)',fontSize:26,fontWeight:800,margin:'2px 0 0',lineHeight:1.15}}>{greeting}{firstName ? `, ${firstName}` : ''}</h1>
          <div style={{fontSize:13,color:'var(--muted)',marginTop:4}}>
            {jobsLoading ? 'Loading today…' : todayJobs.length
              ? `${todayJobs.length} job${todayJobs.length!==1?'s':''} on the board today · ${countBy('completed')} done · ${countBy('on_site')+countBy('en_route')} in the field`
              : 'No jobs on the board today.'}
            {attention.length > 0 && <> · <span style={{color:'var(--red)',fontWeight:600}}>{attention.length} thing{attention.length!==1?'s':''} need{attention.length===1?'s':''} attention</span></>}
          </div>
        </div>
        <div style={{display:'flex',gap:8,flexWrap:'wrap'}}>
          {quickActions.map(a => (
            <button key={a.label} onClick={a.onClick} style={{display:'flex',alignItems:'center',gap:6,padding:'9px 14px',borderRadius:10,fontSize:13,fontWeight:600,cursor:'pointer',
              background:a.primary?'var(--blue)':'var(--surface)',color:a.primary?'#fff':'var(--text)',border:a.primary?'1px solid var(--blue)':'1px solid var(--border)'}}>
              <span style={{fontSize:a.primary?16:13,lineHeight:1}}>{a.icon}</span>{a.label}
            </button>
          ))}
        </div>
      </div>

      {/* ── Period picker ── */}
      <div style={{display:'flex',alignItems:'center',gap:10,flexWrap:'wrap'}}>
        <div role="tablist" style={{display:'flex',gap:2,background:'var(--surface2)',border:'1px solid var(--border)',borderRadius:10,padding:3}}>
          {DASH_PERIODS.map(p => (
            <button key={p.id} role="tab" aria-selected={period===p.id} onClick={() => pickPeriod(p.id)} style={{padding:'6px 14px',borderRadius:7,border:'none',fontSize:12,fontWeight:600,cursor:'pointer',
              background:period===p.id?'var(--surface)':'transparent',color:period===p.id?'var(--text)':'var(--muted)',boxShadow:period===p.id?'0 1px 3px #0000001f':'none'}}>{p.label}</button>
          ))}
        </div>
        <span style={{fontSize:11,color:'var(--muted)'}}>Changes {vsLabel}</span>
        <div style={{flex:1}}/>
        <button onClick={reload} style={{display:'flex',gap:5,alignItems:'center',padding:'6px 12px',background:'var(--surface)',border:'1px solid var(--border)',borderRadius:8,color:'var(--muted)',fontSize:12,cursor:'pointer'}}>
          <Icon n="refresh" size={12}/> Refresh
        </button>
      </div>

      {/* ── KPI tiles (ServiceTitan) ── */}
      <div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(160px,1fr))',gap:10}}>
        {kpis.map(k => (
          <div key={k.label} title={k.hint} style={{background:'var(--surface)',border:'1px solid var(--border)',borderRadius:12,padding:'14px 16px',position:'relative',overflow:'hidden'}}>
            <div style={{position:'absolute',left:0,top:0,bottom:0,width:3,background:k.accent}}/>
            <div style={{fontSize:11,color:'var(--muted)',fontWeight:600,marginBottom:6}}>{k.label}</div>
            {loading && !ov ? <Spinner/> : <>
              <div style={{fontFamily:'var(--font-head)',fontSize:26,fontWeight:800,lineHeight:1,fontVariantNumeric:'tabular-nums'}}>{k.value}</div>
              <div style={{marginTop:8,minHeight:18}}>{k.delta}</div>
            </>}
          </div>
        ))}
      </div>

      {/* ── Trend + Needs attention ── */}
      <div style={{display:'flex',flexWrap:'wrap',gap:14,alignItems:'stretch'}}>
        <Panel title="Sales vs. Collected" style={{flex:'2 1 520px'}} right={
          <div style={{display:'flex',gap:14,fontSize:11,color:'var(--muted)'}}>
            <span><span style={{display:'inline-block',width:8,height:8,borderRadius:2,background:'#4a9eff',marginRight:5}}/>Sales {fmt$(trendSales)}</span>
            <span><span style={{display:'inline-block',width:8,height:8,borderRadius:2,background:'#5daf7c',marginRight:5}}/>Collected {fmt$(trendCollected)}</span>
          </div>
        }>
          {loading && !ov ? <div style={{height:180,display:'flex',alignItems:'center',justifyContent:'center'}}><Spinner/></div> : (
            <div style={{position:'relative'}}>
              <div style={{position:'absolute',left:0,top:0,fontSize:10,color:'var(--muted)',fontFamily:'var(--font-mono)'}}>{fmtK$(trendMax)}</div>
              <div style={{display:'flex',alignItems:'flex-end',gap:trend.length>20?2:6,height:180,paddingTop:16,borderBottom:'1px solid var(--border)'}} onMouseLeave={() => setHoverBar(null)}>
                {trend.map((t,i) => (
                  <div key={i} onMouseEnter={() => setHoverBar(i)} style={{flex:1,height:'100%',display:'flex',alignItems:'flex-end',justifyContent:'center',gap:1,position:'relative',cursor:'default',
                    background:hoverBar===i?'var(--surface2)':'transparent',borderRadius:'4px 4px 0 0'}}>
                    <div style={{width:'42%',maxWidth:18,height:`${(t.sales/trendMax)*100}%`,minHeight:t.sales?2:0,background:'#4a9eff',borderRadius:'3px 3px 0 0'}}/>
                    <div style={{width:'42%',maxWidth:18,height:`${(t.collected/trendMax)*100}%`,minHeight:t.collected?2:0,background:'#5daf7c',borderRadius:'3px 3px 0 0'}}/>
                    {hoverBar===i && (
                      <div style={{position:'absolute',bottom:'100%',left:'50%',transform:'translateX(-50%)',marginBottom:4,background:'var(--text)',color:'var(--surface)',borderRadius:6,padding:'6px 9px',fontSize:11,whiteSpace:'nowrap',zIndex:5,pointerEvents:'none'}}>
                        <div style={{fontWeight:700,marginBottom:2}}>{bucketTitle(t.bucket)}</div>
                        <div>Sales {fmt$(t.sales)}</div><div>Collected {fmt$(t.collected)}</div>
                      </div>
                    )}
                  </div>
                ))}
              </div>
              <div style={{display:'flex',gap:trend.length>20?2:6,marginTop:4}}>
                {trend.map((t,i) => (
                  <div key={i} style={{flex:1,textAlign:'center',fontSize:9,color:'var(--muted)',fontFamily:'var(--font-mono)',overflow:'hidden'}}>
                    {trend.length > 16 && i % 3 !== 0 && i !== trend.length-1 ? '' : bucketLabel(t.bucket)}
                  </div>
                ))}
              </div>
            </div>
          )}
        </Panel>

        <Panel title="Needs Attention" pad={false} style={{flex:'1 1 320px'}} right={attention.length ? <span style={{fontSize:11,fontWeight:700,color:'var(--red)'}}>{attention.length}</span> : null}>
          {loading && !ov ? <div style={{padding:24,display:'flex',justifyContent:'center'}}><Spinner/></div>
            : attention.length === 0 ? (
              <div style={{padding:'28px 18px',textAlign:'center'}}>
                <div style={{fontSize:28}}>✅</div>
                <div style={{fontSize:13,fontWeight:600,marginTop:6}}>You're all caught up</div>
                <div style={{fontSize:12,color:'var(--muted)',marginTop:2}}>Nothing waiting on the office.</div>
              </div>
            ) : attention.map((a,i) => (
              <button key={a.key} onClick={() => onNavigate(a.page)} style={{display:'flex',alignItems:'center',gap:12,width:'100%',textAlign:'left',padding:'10px 18px',background:'none',border:'none',borderTop:i?'1px solid var(--border)':'none',cursor:'pointer',color:'var(--text)'}}
                onMouseEnter={e=>e.currentTarget.style.background='var(--surface2)'} onMouseLeave={e=>e.currentTarget.style.background='none'}>
                <div style={{width:34,height:34,borderRadius:9,background:`${a.tone}18`,display:'flex',alignItems:'center',justifyContent:'center',fontSize:16,flexShrink:0}}>{a.icon}</div>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{fontSize:13,fontWeight:600}}>{a.label}</div>
                  <div style={{fontSize:11,color:'var(--muted)',overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{a.sub}</div>
                </div>
                <div style={{fontFamily:'var(--font-head)',fontSize:18,fontWeight:800,color:a.tone}}>{a.n}</div>
                <span style={{color:'var(--muted)',fontSize:14}}>›</span>
              </button>
            ))}
        </Panel>
      </div>

      {/* ── Today's schedule + Technician scorecard ── */}
      <div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(min(100%,420px),1fr))',gap:14,alignItems:'start'}}>
        <Panel title="Today's Schedule" pad={false} right={<LinkBtn onClick={() => onNavigate('dispatch')}>Open dispatch board →</LinkBtn>}>
          <div style={{display:'flex',gap:6,padding:'0 18px 10px',flexWrap:'wrap'}}>
            {[['scheduled','Scheduled','#a78bfa'],['en_route','En route','#4a9eff'],['on_site','On site','#e8a84a'],['completed','Done','#5daf7c'],['unassigned','Unassigned','#f56565']].map(([s,l,c]) => (
              <span key={s} style={{fontSize:11,color:'var(--muted)',background:'var(--surface2)',border:'1px solid var(--border)',borderRadius:999,padding:'2px 9px'}}>
                <span style={{display:'inline-block',width:6,height:6,borderRadius:'50%',background:c,marginRight:5}}/>{l} <b style={{color:'var(--text)'}}>{countBy(s)}</b>
              </span>
            ))}
          </div>
          {jobsLoading ? <div style={{padding:24,display:'flex',justifyContent:'center'}}><Spinner/></div>
            : todayJobs.length === 0 ? <div style={{padding:'20px 18px',fontSize:13,color:'var(--muted)',textAlign:'center'}}>Nothing scheduled today. <LinkBtn onClick={() => onNavigate('dispatch',{newJob:true})}>Book a job</LinkBtn></div>
            : todayJobs.map((j,i) => {
              const time = j.scheduled_start ? new Date(j.scheduled_start).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}) : '—';
              return (
                <div key={j.id} style={{display:'grid',gridTemplateColumns:'68px 1fr auto',gap:12,alignItems:'center',padding:'9px 18px',borderTop:'1px solid var(--border)'}}>
                  <div style={{fontFamily:'var(--font-mono)',fontSize:12,color:'var(--muted)'}}>{time}</div>
                  <div style={{minWidth:0}}>
                    <div style={{fontSize:13,fontWeight:600,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{j.customer_name || '—'}</div>
                    <div style={{display:'flex',alignItems:'center',gap:6,fontSize:11,color:'var(--muted)',minWidth:0}}>
                      {j.technician_color && <span style={{width:7,height:7,borderRadius:'50%',background:j.technician_color,flexShrink:0}}/>}
                      <span style={{overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{j.technician_name || 'Unassigned'} · {j.job_type || 'Job'}{j.address ? ` · ${j.address}` : ''}</span>
                    </div>
                  </div>
                  <Pill status={j.status}/>
                </div>
              );
            })}
        </Panel>

        <Panel title="Technician Scorecard" pad={false} right={<span style={{fontSize:11,color:'var(--muted)'}}>{DASH_PERIODS.find(p=>p.id===period)?.label}</span>}>
          <div style={{display:'grid',gridTemplateColumns:'1fr 56px 84px 76px 64px',gap:8,padding:'0 18px 6px',fontSize:10,color:'var(--muted)',fontWeight:600,letterSpacing:'.03em'}}>
            <div>TECHNICIAN</div><div style={{textAlign:'right'}}>JOBS</div><div style={{textAlign:'right'}}>SALES</div><div style={{textAlign:'right'}}>AVG TKT</div><div style={{textAlign:'right'}}>CLOSE</div>
          </div>
          {loading && !ov ? <div style={{padding:24,display:'flex',justifyContent:'center'}}><Spinner/></div>
            : techs.length === 0 ? <div style={{padding:'20px 18px',fontSize:13,color:'var(--muted)',textAlign:'center'}}>No active technicians.</div>
            : techs.map((t,i) => {
              const c = t.color || '#5daf7c';
              return (
                <div key={t.id} style={{display:'grid',gridTemplateColumns:'1fr 56px 84px 76px 64px',gap:8,alignItems:'center',padding:'10px 18px',borderTop:'1px solid var(--border)',fontVariantNumeric:'tabular-nums'}}>
                  <div style={{display:'flex',alignItems:'center',gap:10,minWidth:0}}>
                    <div style={{width:30,height:30,borderRadius:'50%',background:`${c}22`,border:`2px solid ${c}66`,display:'flex',alignItems:'center',justifyContent:'center',fontSize:11,fontWeight:700,color:c,fontFamily:'var(--font-mono)',flexShrink:0}}>{t.initials || t.name?.[0]}</div>
                    <div style={{minWidth:0,flex:1}}>
                      <div style={{fontSize:13,fontWeight:600,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{i===0 && t.sales>0 ? '🏆 ' : ''}{t.name}</div>
                      <div style={{height:4,background:'var(--surface2)',borderRadius:2,marginTop:4,overflow:'hidden'}}>
                        <div style={{height:'100%',width:`${(t.sales/techMax)*100}%`,background:c,borderRadius:2}}/>
                      </div>
                    </div>
                  </div>
                  <div style={{textAlign:'right',fontSize:13}}>{t.jobs_completed}</div>
                  <div style={{textAlign:'right',fontSize:13,fontWeight:700}}>{fmt$(t.sales)}</div>
                  <div style={{textAlign:'right',fontSize:13,color:'var(--muted)'}}>{t.avg_ticket ? fmt$(t.avg_ticket) : '—'}</div>
                  <div style={{textAlign:'right',fontSize:13,color:'var(--muted)'}}>{pct(t.close_rate)}</div>
                </div>
              );
            })}
        </Panel>
      </div>
    </div>
  );
}

// ─── JOBS PAGE ────────────────────────────────────────────────
function JobsPage({ onOpenDoc }) {
  const [filter, setFilter] = useState("all");
  // Range preset: '7d' | '30d' | '90d' | '12m' | 'custom'. Custom uses customFrom/customTo.
  const [range, setRange] = useState('30d');
  const todayStr = () => new Date().toISOString().split("T")[0];
  const daysAgoStr = (n) => { const d = new Date(); d.setDate(d.getDate() - n); return d.toISOString().split("T")[0]; };
  const [customFrom, setCustomFrom] = useState(daysAgoStr(30));
  const [customTo,   setCustomTo]   = useState(todayStr());

  const rangeParams = useMemo(() => {
    if (range === '7d')  return { from: daysAgoStr(7),  to: todayStr() };
    if (range === '30d') return { from: daysAgoStr(30), to: todayStr() };
    if (range === '90d') return { from: daysAgoStr(90), to: todayStr() };
    if (range === '12m') return { from: daysAgoStr(365),to: todayStr() };
    if (range === 'custom') return { from: customFrom, to: customTo };
    return { from: daysAgoStr(30), to: todayStr() };
  }, [range, customFrom, customTo]);

  const {data:jobs, loading, reload} = useApi(() => api.getJobs(rangeParams), [rangeParams.from, rangeParams.to]);

  const filtered = filter==="all" ? (jobs||[]) : (jobs||[]).filter(j=>j.status===filter);

  // Drill-in state — clicking a row opens a modal with that job's estimates + invoices.
  const [selectedJob, setSelectedJob] = useState(null);
  const [jobTab, setJobTab] = useState('estimates');
  const [jobEstimates, setJobEstimates] = useState(null);
  const [jobInvoices, setJobInvoices]   = useState(null);
  useEffect(() => {
    if (!selectedJob) return;
    setJobEstimates(null); setJobInvoices(null); setJobTab('estimates');
    api.getEstimates({ job_id: selectedJob.id })
      .then(r => setJobEstimates(Array.isArray(r) ? r : (r?.estimates || [])))
      .catch(() => setJobEstimates([]));
    api.getInvoices({ job_id: selectedJob.id, type: 'invoice' })
      .then(r => setJobInvoices(Array.isArray(r) ? r : []))
      .catch(() => setJobInvoices([]));
  }, [selectedJob?.id]);
  const closeJobModal = () => setSelectedJob(null);
  const fmt$ = (n) => '$' + parseFloat(n||0).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');

  return (
    <div style={{animation:"fadeUp .4s ease"}}>
      <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:18}}>
        <div style={{fontFamily:"var(--font-head)",fontSize:22,fontWeight:800,flex:1}}>Jobs</div>
        <button onClick={reload} style={{display:"flex",gap:6,alignItems:"center",padding:"6px 12px",background:"var(--surface2)",border:"1px solid var(--border)",borderRadius:8,color:"var(--muted)",fontSize:12}}>
          <Icon n="refresh" size={13} color="#64748b"/> Refresh
        </button>
        <button style={{display:"flex",alignItems:"center",gap:6,padding:"8px 16px",background:"var(--amberdim)",border:"1px solid var(--amber)",borderRadius:8,color:"var(--amber)",fontSize:12,fontWeight:600}}>
          <Icon n="plus" size={14} color="#e8a84a"/> New Job
        </button>
      </div>
      {/* Range presets */}
      <div style={{display:"flex",gap:8,marginBottom:12,alignItems:"center",flexWrap:"wrap"}}>
        {[['7d','7 days'],['30d','30 days'],['90d','90 days'],['12m','12 months'],['custom','Custom range']].map(([id,lb])=>{
          const on = range===id;
          return (
            <button key={id} onClick={()=>setRange(id)}
              style={{padding:"7px 16px",borderRadius:8,cursor:"pointer",fontSize:13,fontWeight:on?800:500,
                background:on?"var(--red)":"var(--surface)",
                border:`1px solid ${on?"var(--red)":"var(--border)"}`,
                color:on?"#fff":"var(--muted)"}}>
              {lb}
            </button>
          );
        })}
        {range==='custom' && (
          <div style={{display:"flex",gap:6,alignItems:"center",marginLeft:8,padding:'6px 10px',background:'var(--surface)',border:'1px solid var(--border)',borderRadius:8}}>
            <input type="date" value={customFrom} onChange={e=>setCustomFrom(e.target.value)}
              style={{background:'var(--surface2)',border:'1px solid var(--border)',borderRadius:6,padding:'4px 8px',color:'var(--text)',fontSize:12}}/>
            <span style={{color:'var(--muted)',fontSize:12}}>→</span>
            <input type="date" value={customTo} onChange={e=>setCustomTo(e.target.value)}
              style={{background:'var(--surface2)',border:'1px solid var(--border)',borderRadius:6,padding:'4px 8px',color:'var(--text)',fontSize:12}}/>
          </div>
        )}
      </div>

      {/* Status filter */}
      <div style={{display:"flex",gap:6,marginBottom:14}}>
        {["all","scheduled","en_route","on_site","completed"].map(s=>(
          <button key={s} onClick={()=>setFilter(s)} style={{padding:"5px 14px",background:filter===s?"var(--amberdim)":"var(--surface)",border:`1px solid ${filter===s?"var(--amber)":"var(--border)"}`,borderRadius:20,color:filter===s?"var(--amber)":"var(--muted)",fontSize:11,fontFamily:"var(--font-mono)"}}>
            {s.replace("_"," ").toUpperCase()}
          </button>
        ))}
      </div>
      {loading ? (
        <div style={{display:"flex",justifyContent:"center",padding:40}}><Spinner/></div>
      ) : (
        <div style={{background:"var(--surface)",border:"1px solid var(--border)",borderRadius:12,overflow:"hidden"}}>
          <table style={{width:"100%",borderCollapse:"collapse"}}>
            <thead>
              <tr style={{borderBottom:"1px solid var(--border2)",background:"var(--surface2)"}}>
                {["Job #","Customer","Type","Technician","Status","Scheduled"].map((h,i)=>(
                  <th key={h} style={{padding:"10px 14px",textAlign:"left",fontSize:10,fontFamily:"var(--font-mono)",color:"var(--muted)",letterSpacing:".07em",fontWeight:500}}>{h.toUpperCase()}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {filtered.map((job,i) => (
                <tr key={job.id}
                  onClick={()=>setSelectedJob(job)}
                  style={{borderBottom:"1px solid var(--border)",animation:`fadeUp .3s ease both`,animationDelay:`${i*.04}s`,cursor:"pointer"}}
                  onMouseEnter={e=>e.currentTarget.style.background="var(--surface2)"}
                  onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
                  <td style={{padding:"10px 14px",fontFamily:"var(--font-mono)",fontSize:12,color:"var(--amber)",fontWeight:600}}>{job.display_number || '#'+job.job_number}</td>
                  <td style={{padding:"10px 14px"}}>
                    <div style={{fontSize:13,fontWeight:500}}>{job.customer_name}</div>
                    <div style={{fontSize:10,color:"var(--muted)"}}>{job.address}</div>
                  </td>
                  <td style={{padding:"10px 14px"}}>
                    <div style={{fontSize:12,color:"#9ca3af"}}>{job.job_type||"—"}</div>
                    {job.description && <div style={{fontSize:11,color:"var(--muted)",marginTop:2,maxWidth:260,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{job.description.replace(/\n/g,' ')}</div>}
                  </td>
                  <td style={{padding:"10px 14px"}}>
                    {job.technician_name ? (
                      <div style={{display:"flex",alignItems:"center",gap:6}}>
                        <div style={{width:8,height:8,borderRadius:"50%",background:job.technician_color||"#64748b"}}/>
                        <span style={{fontSize:12}}>{job.technician_name}</span>
                      </div>
                    ) : <span style={{fontSize:11,color:"var(--muted)"}}>Unassigned</span>}
                  </td>
                  <td style={{padding:"10px 14px"}}><Pill status={job.status}/></td>
                  <td style={{padding:"10px 14px",fontSize:11,fontFamily:"var(--font-mono)",color:"var(--muted)"}}>
                    {job.scheduled_start ? new Date(job.scheduled_start).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"}) : "—"}
                  </td>
                </tr>
              ))}
              {filtered.length===0 && (
                <tr><td colSpan={6} style={{padding:"30px",textAlign:"center",color:"var(--muted)",fontSize:13}}>No jobs found</td></tr>
              )}
            </tbody>
          </table>
        </div>
      )}

      {/* Job drill-in modal — shows estimates + invoices for the clicked job */}
      {selectedJob && (
        <div onClick={closeJobModal}
          style={{position:'fixed',inset:0,background:'rgba(0,0,0,0.55)',zIndex:1000,display:'flex',alignItems:'center',justifyContent:'center',padding:20,animation:'fadeIn .15s ease'}}>
          <div onClick={e=>e.stopPropagation()}
            style={{background:'var(--bg)',border:'1px solid var(--border2)',borderRadius:14,width:'100%',maxWidth:900,maxHeight:'85vh',display:'flex',flexDirection:'column',overflow:'hidden',boxShadow:'0 20px 60px rgba(0,0,0,.5)'}}>

            {/* Header */}
            <div style={{padding:'16px 20px',borderBottom:'1px solid var(--border)',background:'var(--surface)',display:'flex',alignItems:'center',gap:14}}>
              <div style={{fontFamily:'var(--font-mono)',fontSize:12,color:'var(--amber)',fontWeight:700}}>{selectedJob.display_number || '#'+selectedJob.job_number}</div>
              <div style={{flex:1}}>
                <div style={{fontSize:16,fontWeight:800,color:'var(--text)'}}>{selectedJob.customer_name}</div>
                <div style={{fontSize:11,color:'var(--muted)',marginTop:2}}>
                  {selectedJob.job_type || 'Service Call'} · <Pill status={selectedJob.status}/> {selectedJob.address ? '· ' + selectedJob.address : ''}
                </div>
              </div>
              <button onClick={closeJobModal} style={{background:'var(--surface2)',border:'1px solid var(--border)',borderRadius:20,width:32,height:32,color:'var(--muted)',cursor:'pointer',fontSize:14,display:'flex',alignItems:'center',justifyContent:'center'}}>✕</button>
            </div>

            {/* Tabs */}
            <div style={{display:'flex',gap:6,padding:'12px 16px 0',borderBottom:'1px solid var(--border)',background:'var(--surface)'}}>
              {[['estimates','📄 Estimates', (jobEstimates||[]).length],
                ['invoices','🧾 Invoices',  (jobInvoices||[]).length]].map(([id,lb,ct])=>{
                const on = jobTab===id;
                return (
                  <button key={id} onClick={()=>setJobTab(id)}
                    style={{padding:'8px 16px',borderRadius:'7px 7px 0 0',border:'none',borderBottom:'2px solid '+(on?'var(--amber)':'transparent'),background:'transparent',color:on?'var(--amber)':'var(--muted)',fontSize:13,fontWeight:on?700:500,cursor:'pointer'}}>
                    {lb} {ct>0?<span style={{fontSize:10,marginLeft:4,background:'var(--surface2)',padding:'1px 6px',borderRadius:10,color:on?'var(--amber)':'var(--muted)'}}>{ct}</span>:null}
                  </button>
                );
              })}
            </div>

            {/* Body */}
            <div style={{flex:1,overflow:'auto',padding:'14px 18px'}}>
              {jobTab==='estimates' && (
                jobEstimates===null ? <div style={{display:'flex',justifyContent:'center',padding:30}}><Spinner/></div>
                : jobEstimates.length===0 ? <div style={{padding:30,textAlign:'center',color:'var(--muted)',fontSize:13}}>No estimates on this job yet.</div>
                : jobEstimates.map(e => (
                    <div key={e.id}
                      onClick={()=>{ closeJobModal(); onOpenDoc && onOpenDoc('estimates', e.id); }}
                      style={{display:'flex',alignItems:'center',gap:12,padding:'10px 12px',border:'1px solid var(--border)',borderRadius:8,marginBottom:8,background:'var(--surface)',cursor:'pointer',transition:'background .15s'}}
                      onMouseEnter={ev=>ev.currentTarget.style.background='var(--surface2)'}
                      onMouseLeave={ev=>ev.currentTarget.style.background='var(--surface)'}>
                      <div style={{fontFamily:'var(--font-mono)',fontSize:11,color:'#a78bfa',minWidth:120,fontWeight:700}}>{e.display_number || '#'+String(e.id).slice(0,8)}</div>
                      <div style={{flex:1,fontSize:13}}>{e.customer_name || '—'}</div>
                      <div style={{fontFamily:'var(--font-mono)',fontSize:13,fontWeight:700,color:'var(--green)'}}>{fmt$(e.total)}</div>
                      <Pill status={e.status}/>
                      <span style={{color:'var(--muted)',fontSize:18}}>›</span>
                    </div>
                  ))
              )}
              {jobTab==='invoices' && (
                jobInvoices===null ? <div style={{display:'flex',justifyContent:'center',padding:30}}><Spinner/></div>
                : jobInvoices.length===0 ? <div style={{padding:30,textAlign:'center',color:'var(--muted)',fontSize:13}}>No invoices on this job yet.</div>
                : jobInvoices.map(inv => (
                    <div key={inv.id}
                      onClick={()=>{ closeJobModal(); onOpenDoc && onOpenDoc('invoices', inv.id); }}
                      style={{display:'flex',alignItems:'center',gap:12,padding:'10px 12px',border:'1px solid var(--border)',borderRadius:8,marginBottom:8,background:'var(--surface)',cursor:'pointer',transition:'background .15s'}}
                      onMouseEnter={ev=>ev.currentTarget.style.background='var(--surface2)'}
                      onMouseLeave={ev=>ev.currentTarget.style.background='var(--surface)'}>
                      <div style={{fontFamily:'var(--font-mono)',fontSize:11,color:'var(--green)',minWidth:120,fontWeight:700}}>{inv.display_number || '#'+String(inv.id).slice(0,8)}</div>
                      <div style={{flex:1,fontSize:13}}>{inv.customer_name || '—'}</div>
                      <div style={{fontFamily:'var(--font-mono)',fontSize:13,fontWeight:700,color:'var(--green)'}}>{fmt$(inv.total)}</div>
                      <Pill status={inv.status}/>
                      <span style={{color:'var(--muted)',fontSize:18}}>›</span>
                    </div>
                  ))
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

